 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    border = next(v for row in grid for v in row if v != 1 and v != 0) if 1 not in [v for row in grid for v in row] else None
    # The frame color is the most common non-background color; enclosed interiors are painted next color.
    counts = {}
    for row in grid:
        for v in row:
            if v != 1:
                counts[v] = counts.get(v, 0) + 1
    frame = max(counts, key=counts.get)
    fill = (frame + 1) % 10
    out = [r[:] for r in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 or grid[r][c] == frame or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); comp=[]; touches=False
            while q:
                y,x=q.popleft(); comp.append((y,x))
                if y==0 or x==0 or y==h-1 or x==w-1: touches=True
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx] != frame:
                        seen.add((yy,xx)); q.append((yy,xx))
            if not touches and comp:
                for y,x in comp:
                    if grid[y][x] != 1: out[y][x]=fill
    return out

if __name__ == '__main__':
    g=[[1,1,1,5,1,1,1,1,1,1,1,1,1,5,1,1,1,1,1,1,1,1,5,1] for _ in range(26)]
    g[5][23]=5
    for r in range(15,20):
        for c in range(5):
            if r in (15,19) or c in (0,4): g[r][c]=5
    for r in range(15,20):
        for c in range(11,15):
            if r in (15,19) or c in (11,14): g[r][c]=5
    for r in range(17,18):
        for c in range(4,12): g[r][c]=5
    print(transform(g))
    d=[[0]*13 for _ in range(11)]
    for r in range(11): d[r][10]=3
    for c in range(9,13): d[5][c]=3
    for c in range(13): d[6][c]=3 if c!=10 and c!=11 else 0
    for r in range(7,10): d[r][9]=3
    for r in range(6,10): d[r][12]=3
    d[9][10]=3; d[9][11]=3
    print(transform(d))
    assert transform(d)[7][10]==4
    assert transform(d)[8][11]==4
    assert transform(g)[16][1]==6 and transform(g)[17][12]==6
",
